// SPDX-License-Identifier: Unlicense
pragma solidity ^0.8.26;


contract StringUtils1 {
	// UTILITY FUNCTIONS

	function stripWhitespace(string memory input) public pure returns (string memory) {
		bytes memory inputBytes = bytes(input);

		// Find the start of the non-whitespace characters
		uint start = 0;
		while (start < inputBytes.length && (inputBytes[start] == 0x20 || inputBytes[start] == 0x09)) {
			start++;
		}

		// Find the end of the non-whitespace characters
		uint end = inputBytes.length;
		while (end > start && (inputBytes[end - 1] == 0x20 || inputBytes[end - 1] == 0x09)) {
			end--;
		}

		// Create a new byte array with the stripped content
		uint strippedLength = end - start;
		bytes memory strippedBytes = new bytes(strippedLength);
		for (uint i = 0; i < strippedLength; i++) {
			strippedBytes[i] = inputBytes[start + i];
		}

		return string(strippedBytes);
	}

	// https://gist.github.com/ottodevs/c43d0a8b4b891ac2da675f825b1d1dbf
	function _toLower(string memory str) public pure returns (string memory) {
		bytes memory bStr = bytes(str);
		bytes memory bLower = new bytes(bStr.length);

		for (uint i = 0; i < bStr.length; i++) {
			// Uppercase character
			if ((bStr[i] >= 0x41) && (bStr[i] <= 0x5A)) {
				// Add 32 to make it lowercase
				bLower[i] = bytes1(uint8(bStr[i]) + 32);
			} else {
				bLower[i] = bStr[i];
			}
		}

		return string(bLower);
	}

	function _clean(string memory str) public pure returns (string memory) {
		bytes memory bStr = bytes(str);
		bytes memory bLower = new bytes(bStr.length);
		for (uint i = 0; i < bStr.length; i++) {
			// Uppercase character...
			if ((bStr[i] >= 0x41) && (bStr[i] <= 0x5A)) {
				// So we add 32 to make it lowercase
				bLower[i] = bytes1(uint8(bStr[i]) + 32);
			} else if (bStr[i] == '$') {
				bLower[i] = 's';
			} else if (bStr[i] == '@') {
				bLower[i] = 'a';
			} else if (bStr[i] == '0') {
				bLower[i] = 'o';
			} else if (bStr[i] == '1') {
				bLower[i] = 'i';
			} else {
				bLower[i] = bStr[i];
			}
		}
		return string(bLower);
	}

	// https://ethereum.stackexchange.com/questions/69307/find-word-in-string-solidity
	function contains(string memory what, string memory where) public pure returns (bool) {
		bytes memory whatBytes = bytes (what);
		bytes memory whereBytes = bytes (where);

		if (whereBytes.length < whatBytes.length)
			return false;

		bool found = false;
		for (uint i = 0; i <= whereBytes.length - whatBytes.length; i++) {
			bool flag = true;
			for (uint j = 0; j < whatBytes.length; j++)
				if (whereBytes [i + j] != whatBytes [j]) {
					flag = false;
					break;
				}
			if (flag) {
				found = true;
				break;
			}
		}

		return found;
	}

	// Listen, we're mostly wholesome around here.  Rules are VERY relaxed: no sexual nonsense, and no demon worship.
	// Basically anything else goes, which is quite generous.
	function isBadString(string memory input) public pure returns (bool) {
		string memory lowered = _clean(input);
		if (contains("sex", lowered))
			return true;
		if (contains("69", lowered))
			return true;
		if (contains("666", lowered))
			return true;
		if (contains("nude", lowered))
			return true;
		if (contains("boob", lowered))
			return true;
		if (contains("penis", lowered))
			return true;
		if (contains("vagina", lowered))
			return true;
		if (contains("dick", lowered))
			return true;
		if (contains("cum", lowered))
			return true;
		if (contains("porn", lowered))
			return true;
		if (contains("pussy", lowered))
			return true;
		return false;
	}

	// https://ethereum-magicians.org/t/eip-7054-gas-efficient-square-root-calculation-with-binary-search-approach/14539
	// Modified to work better for smaller numbers
	function sqrt(uint64 x) public pure returns (uint32) {
		if (x == 0) return 0;
		else{
			uint64 xx = x;
			uint64 r = 1;
			//if (xx >= 0x100000000000000000000000000000000) { xx >>= 128; r <<= 64; }
			//if (xx >= 0x10000000000000000) { xx >>= 64; r <<= 32; }
			if (xx >= 0x100000000) { xx >>= 32; r <<= 16; }
			if (xx >= 0x10000) { xx >>= 16; r <<= 8; }
			if (xx >= 0x100) { xx >>= 8; r <<= 4; }
			if (xx >= 0x10) { xx >>= 4; r <<= 2; }
			if (xx >= 0x8) { r <<= 1; }
			r = (r + x / r) >> 1;
			r = (r + x / r) >> 1;
			r = (r + x / r) >> 1;
			r = (r + x / r) >> 1;
			r = (r + x / r) >> 1;
			r = (r + x / r) >> 1;
			r = (r + x / r) >> 1;
			uint64 r1 = x / r;
			return uint32 (r < r1 ? r : r1);
		}
	}
}
